import sys

def next_n(x):
    s = 0
    while x:
        d = x % 10
        s += d * d
        x //= 10
    return s

def is_happy_brute(n):
    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = next_n(n)
    return n == 1

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    print('true' if is_happy_brute(n) else 'false')

import sys

def next_n(x):
    s = 0
    while x:
        d = x % 10
        s += d * d
        x //= 10
    return s

def is_happy_best(n):
    while n != 1 and n != 4:
        n = next_n(n)
    return n == 1

